def load(self, fragment):
    self.path.load('')
    self.query.load('')

    if fragment is None:
        fragment = ''

    toks = fragment.split('?', 1)
    if len(toks) == 0:
        self._path.load('')
        self._query.load('')
    elif len(toks) == 1:
        if '=' not in fragment:
            self._query.load(fragment)
        else:
            self._path.load(fragment)
    else:
        if '=' not in toks[1]:
            self._path.load(toks[0])
            self._query.load(toks[1])
        else:
            self._path.load(fragment)
